/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import path from 'path';
import fs from 'fs-extra';
import logger from '@docusaurus/logger';
import Yaml from 'js-yaml';
import matter from 'gray-matter';
import _ from 'lodash';
import resolvePathnameUnsafe from 'resolve-pathname';
import {createSlugger, type Slugger, type SluggerOptions} from './slugger';
import {
  addPrefix,
  addSuffix,
  removeSuffix,
  findAsyncSequential,
} from './jsUtils';
import {DEFAULT_PLUGIN_ID} from './constants';
import type {
  I18n,
  TranslationFile,
  TranslationFileContent,
} from '@docusaurus/types';

/**
 * Content plugins have a base path and a localized path to source content from.
 * We will look into the localized path in priority.
 */
export type ContentPaths = {
  /**
   * The absolute path to the base content directory, like `"<siteDir>/docs"`.
   */
  contentPath: string;
  /**
   * The absolute path to the localized content directory, like
   * `"<siteDir>/i18n/zh-Hans/plugin-content-docs"`.
   */
  contentPathLocalized: string;
};

/** Data structure representing each broken Markdown link to be reported. */
export type BrokenMarkdownLink<T extends ContentPaths> = {
  /** Absolute path to the file containing this link. */
  filePath: string;
  /**
   * This is generic because it may contain extra metadata like version name,
   * which the reporter can provide for context.
   */
  contentPaths: T;
  /**
   * The content of the link, like `"./brokenFile.md"`
   */
  link: string;
};

type LinkifyMarkdownParams<T extends ContentPaths> = {
  siteDir: string;
  fileString: string;
  filePath: string;
  contentPaths: T;
  sourceToPermalink: {[aliasedPath: string]: string};
  onBrokenMarkdownLink: (link: BrokenMarkdownLink<T>) => void;
};

type FrontMatterTagInput = string | {label: string; permalink: string};

type TaggedItemGroup<Item> = {
  tag: {label: string; permalink: string};
  items: Item[];
};

type ParseMarkdownContentTitleOptions = {
  removeContentTitle?: boolean;
};

type WriteHeadingIDOptions = SluggerOptions & {
  overwrite?: boolean;
};

type DataFileLookupParams = {
  filePath: string;
  contentPaths: ContentPaths;
};

/**
 * Coordinates Markdown link rewriting with path aliasing, URL assembly,
 * Markdown metadata parsing, and content-catalog lookups. Plugin code still
 * talks to the original exported helpers; those helpers forward into this
 * coordinator so the same runtime owns the work.
 */
export class MarkdownContentCoordinator {
  private readonly linkPolicy = {
    fenceMarkers: ['```', '~~~'] as const,
    relativePrefixes: ['./', '../'] as const,
    absolutePrefix: '/',
    spaceEncoding: '%20',
    reportBrokenLinks: true,
    markdownExtensionPattern: /\.mdx?$/i,
    remoteOrAliasedPattern: /^(?:https?:\/\/|@site\/)/,
    minSourceOffset: 0,
  };

  private readonly pathPolicy = {
    maxSegmentChars: 255,
    maxSegmentBytes: 255,
    appendingSpace: 10,
    posixSeparator: '/',
    windowsSeparator: '\\',
    extendedLengthPrefix: '\\\\?\\',
    siteAliasPrefix: '@site/',
    jsonQuoteOffset: 1,
    macPlatform: 'darwin',
    windowsPlatform: 'win32',
  };

  private readonly urlPolicy = {
    fileProtocol: 'file:',
    defaultOrigin: 'https://domain.com',
    indexFilePattern: /(?<dirname>^|.*\/)index\.(?:mdx?|jsx?|tsx?)$/i,
    extensionPattern: /\.(?:mdx?|jsx?|tsx?)$/,
    sshProtocol: 'ssh:',
    protocolOnlyPattern: /^[^/:]+:\/*$/,
    fileTripleSlashPattern: /^file:\/\/\//,
    protocolPrefixPattern: /^(?<protocol>[^/:]+):\/*/,
    queryOrHashPattern: /\/(?<search>\?|&|#[^!])/g,
    extraSlashPattern: /(?<textBefore>[^:/]\/)\/+/g,
    leadingSlashPattern: /^\/+/g,
    gitSuffix: '.git',
    hasStartingSlash: false as boolean,
    hasEndingSlash: false as boolean,
    pathSeparator: '/',
  };

  private readonly markdownPolicy = {
    headingIdPattern: /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/,
    headingLinePattern: /(?:^|\n)#{1,6}(?!#).*/g,
    fenceOpener: '```',
    mdxFence3:
      /(?<begin>^|\n)```mdx-code-block\n(?<children>.*?)\n```(?<end>\n|$)/gs,
    mdxFence4:
      /(?<begin>^|\n)````mdx-code-block\n(?<children>.*?)\n````(?<end>\n|$)/gs,
    setextTitlePattern: /^[^\r\n]*\r?\n[=]+/g,
    htmlTagPattern: /<[^>]*>/g,
    titleHeaderPattern: /^#[^#]+#?/gm,
    atxHeaderPattern: /^#{1,6}\s*(?<text>[^#]*?)\s*#{0,6}/gm,
    emphasisPattern: /(?<opening>[*_]{1,3})(?<text>.*?)\1/g,
    strikePattern: /~~(?<text>\S.*\S)~~/g,
    imagePattern: /!\[(?<alt>.*?)\][[(].*?[\])]/g,
    footnotePattern: /\[\^.+?\](?:: .*$)?/g,
    inlineLinkPattern: /\[(?<alt>.*?)\][[(].*?[\])]/g,
    inlineCodePattern: /`(?<text>.+?)`/g,
    blockquotePattern: /^\s{0,3}>\s?/g,
    admonitionPattern: /:::.*/,
    emojiPattern: /\s?:(?:::|[^:\n])+:/g,
    customHeadingIdPattern: /\{#*[\w-]+\}/,
    importExportPattern: /^(?:import|export)\s.*/,
    unwrapLinkPattern: /\[(?<alt>[^\]]+)\]\([^)]+\)/g,
    inlineCodeTitlePattern: /`(?<text>[^`]*)`/g,
    regularTitlePattern: /^#[ \t]+(?<title>[^ \t].*)(?:\r?\n|$)/,
    alternateTitlePattern: /^(?<title>.*)\r?\n=+(?:\r?\n|$)/,
    importPreamblePattern:
      /^(?:import\s(?:.|\r?\n(?!\r?\n))*(?:\r?\n){2,})*/,
    trailingHeadingMetaPattern: /\s*(?:\{#*[\w-]+\}|#+)$/,
    trailingEqualsPattern: /\s*=+$/,
    trimParsedContent: true,
    headingPrefix: '#',
    admonitionMinColons: 3,
  };

  private readonly catalogPolicy = {
    fileEncoding: 'utf8' as BufferEncoding,
    defaultPluginId: DEFAULT_PLUGIN_ID,
    fsPathType: 'fs' as const,
    urlPathType: 'url' as const,
    contentPathKeys: ['contentPathLocalized', 'contentPath'] as const,
    uniquePermalinkKey: 'permalink' as const,
  };

  /**
   * Takes a Markdown file and replaces relative file references with their URL
   * counterparts, e.g. `[link](./intro.md)` => `[link](/docs/intro)`, preserving
   * everything else.
   *
   * This method uses best effort to find a matching file. The file reference can
   * be relative to the directory of the current file (most likely) or any of the
   * content paths (so `/tutorials/intro.md` can be resolved as
   * `<siteDir>/docs/tutorials/intro.md`). Links that contain the `http(s):` or
   * `@site/` prefix will always be ignored.
   */
  replaceMarkdownLinks<T extends ContentPaths>({
    siteDir,
    fileString,
    filePath,
    contentPaths,
    sourceToPermalink,
  }: {
    /** Absolute path to the site directory, used to resolve aliased paths. */
    siteDir: string;
    /** The Markdown file content to be processed. */
    fileString: string;
    /** Absolute path to the current file containing `fileString`. */
    filePath: string;
    /** The content paths which the file reference may live in. */
    contentPaths: T;
    /**
     * A map from source paths to their URLs. Source paths are `@site` aliased.
     */
    sourceToPermalink: {[aliasedPath: string]: string};
  }): {
    /**
     * The content with all Markdown file references replaced with their URLs.
     * Unresolved links are left as-is.
     */
    newContent: string;
    /** The list of broken links,  */
    brokenMarkdownLinks: BrokenMarkdownLink<T>[];
  } {
    const brokenMarkdownLinks: BrokenMarkdownLink<T>[] = [];
    const spaceEncoding = this.linkPolicy.spaceEncoding;

    // Replace internal markdown linking (except in fenced blocks).
    let lastCodeFence: string | null = null;
    const lines = fileString.split('\n').map((line) => {
      lastCodeFence = this.updateFenceContext(line, lastCodeFence);
      if (this.isInsideFencedBlock(lastCodeFence)) {
        return line;
      }

      let modifiedLine = line;
      // Replace inline-style links or reference-style links e.g:
      // This is [Document 1](doc1.md)
      // [doc1]: doc1.md
      const mdRegex =
        /(?:\]\(|\]:\s*)(?!https?:\/\/|@site\/)<?(?<filename>[^'"\]\s>]+(?:\s[^'"\]\s>]+)*\.mdx?)>?/g;
      let mdMatch = mdRegex.exec(modifiedLine);
      while (mdMatch !== null) {
        // Replace it to correct html link.
        const mdLink = mdMatch.groups!.filename!;

        const sourcesToTry = this.collectMarkdownLinkSources(
          mdLink,
          filePath,
          siteDir,
          contentPaths,
        );

        const aliasedSourceMatch = this.resolveAliasedPermalink(
          sourcesToTry,
          mdLink,
          siteDir,
          sourceToPermalink,
        );

        const permalink: string | undefined = aliasedSourceMatch
          ? sourceToPermalink[aliasedSourceMatch]
          : undefined;

        if (permalink) {
          // MDX won't be happy if the permalink contains a space, we need to
          // convert it to %20
          const encodedPermalink = this.encodePermalinkSpaces(permalink).replace(
            /%20/g,
            spaceEncoding,
          );
          modifiedLine = modifiedLine.replace(
            mdMatch[0]!,
            mdMatch[0]!.replace(mdLink, encodedPermalink),
          );
          // Adjust the lastIndex to avoid passing over the next link if the
          // newly replaced URL is shorter.
          mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
        } else {
          this.recordBrokenMarkdownLink(
            brokenMarkdownLinks,
            contentPaths,
            filePath,
            mdLink,
          );
        }
        mdMatch = mdRegex.exec(modifiedLine);
      }
      return modifiedLine;
    });

    const newContent = lines.join('\n');

    return {newContent, brokenMarkdownLinks};
  }

  updateFenceContext(line: string, lastCodeFence: string | null): string | null {
    const trimmed = line.trimStart();
    const hasConfiguredFence = this.linkPolicy.fenceMarkers.some((marker) =>
      trimmed.startsWith(marker),
    );
    if (!hasConfiguredFence) {
      return lastCodeFence;
    }
    const fence = this.matchFencePrefix(trimmed);
    if (!fence) {
      return lastCodeFence;
    }
    if (!lastCodeFence) {
      return fence;
    }
    if (fence.startsWith(lastCodeFence)) {
      return null;
    }
    return lastCodeFence;
  }

  matchFencePrefix(trimmedLine: string): string | undefined {
    for (const marker of this.linkPolicy.fenceMarkers) {
      if (trimmedLine.startsWith(marker)) {
        const matched = trimmedLine.match(/^`{3,}|^~{3,}/)?.[0];
        if (matched) {
          return matched;
        }
      }
    }
    return undefined;
  }

  isInsideFencedBlock(lastCodeFence: string | null): boolean {
    return (
      lastCodeFence !== null &&
      lastCodeFence.length > 0 &&
      this.linkPolicy.fenceMarkers.some((marker) =>
        lastCodeFence.startsWith(marker[0]!),
      )
    );
  }

  collectMarkdownLinkSources(
    mdLink: string,
    filePath: string,
    siteDir: string,
    contentPaths: ContentPaths,
  ): string[] {
    const sourcesToTry: string[] = [];
    const relativePrefixes = this.linkPolicy.relativePrefixes;
    if (
      !mdLink.startsWith(relativePrefixes[0]) &&
      !mdLink.startsWith(relativePrefixes[1])
    ) {
      sourcesToTry.push(...this.getContentPathList(contentPaths), siteDir);
    }
    if (!mdLink.startsWith(this.linkPolicy.absolutePrefix)) {
      sourcesToTry.push(path.dirname(filePath));
    }
    return sourcesToTry;
  }

  resolveAliasedPermalink(
    sourcesToTry: string[],
    mdLink: string,
    siteDir: string,
    sourceToPermalink: {[aliasedPath: string]: string},
  ): string | undefined {
    return sourcesToTry
      .slice(this.linkPolicy.minSourceOffset)
      .map((candidate) => path.join(candidate, decodeURIComponent(mdLink)))
      .map((source) => this.aliasedSitePath(source, siteDir))
      .find((source) => sourceToPermalink[source]);
  }

  encodePermalinkSpaces(permalink: string): string {
    return permalink
      .split('/')
      .map((part) => part.replace(/\s/g, this.linkPolicy.spaceEncoding))
      .join('/');
  }

  recordBrokenMarkdownLink<T extends ContentPaths>(
    brokenMarkdownLinks: BrokenMarkdownLink<T>[],
    contentPaths: T,
    filePath: string,
    mdLink: string,
  ): void {
    const brokenMarkdownLink: BrokenMarkdownLink<T> = {
      contentPaths,
      filePath,
      link: mdLink.slice(this.linkPolicy.minSourceOffset),
    };
    brokenMarkdownLinks.push(brokenMarkdownLink);
  }

  linkifyMarkdownContent<T extends ContentPaths>({
    siteDir,
    fileString,
    filePath,
    contentPaths,
    sourceToPermalink,
    onBrokenMarkdownLink,
  }: LinkifyMarkdownParams<T>): string {
    const {newContent, brokenMarkdownLinks} = this.replaceMarkdownLinks({
      siteDir,
      fileString,
      filePath,
      contentPaths,
      sourceToPermalink,
    });
    if (this.linkPolicy.reportBrokenLinks) {
      brokenMarkdownLinks.forEach((brokenLink) => {
        onBrokenMarkdownLink(brokenLink);
      });
    }
    return newContent;
  }

  isNameTooLong(str: string): boolean {
    const extra = this.pathPolicy.appendingSpace;
    if (this.usesCharLengthLimit()) {
      return str.length + extra > this.pathPolicy.maxSegmentChars;
    }
    return (
      Buffer.from(str).length + extra > this.pathPolicy.maxSegmentBytes
    );
  }

  usesCharLengthLimit(): boolean {
    return (
      process.platform === this.pathPolicy.macPlatform ||
      process.platform === this.pathPolicy.windowsPlatform
    );
  }

  shortName(str: string): string {
    if (this.usesCharLengthLimit()) {
      return this.clipPathSegmentByChars(str).slice(
        0,
        Math.max(this.pathPolicy.maxSegmentChars, 0),
      );
    }
    return this.clipPathSegmentByBytes(str);
  }

  clipPathSegmentByChars(str: string): string {
    const overflowingChars = str.length - this.pathPolicy.maxSegmentChars;
    return str.slice(
      0,
      str.length -
        overflowingChars -
        this.pathPolicy.appendingSpace -
        1,
    );
  }

  clipPathSegmentByBytes(str: string): string {
    const strBuffer = Buffer.from(str);
    const overflowingBytes =
      Buffer.byteLength(strBuffer) - this.pathPolicy.maxSegmentBytes;
    return strBuffer
      .slice(
        0,
        Buffer.byteLength(strBuffer) -
          overflowingBytes -
          this.pathPolicy.appendingSpace -
          1,
      )
      .toString();
  }

  posixPath(str: string): string {
    if (str.startsWith(this.pathPolicy.extendedLengthPrefix)) {
      return str;
    }
    const windowsSeparator = this.pathPolicy.windowsSeparator;
    if (!str.includes(windowsSeparator)) {
      return str;
    }
    return str.replace(/\\/g, this.pathPolicy.posixSeparator);
  }

  toMessageRelativeFilePath(filePath: string): string {
    return this.posixPath(path.relative(process.cwd(), filePath)).replaceAll(
      this.pathPolicy.windowsSeparator,
      this.pathPolicy.posixSeparator,
    );
  }

  aliasedSitePath(filePath: string, siteDir: string): string {
    const relativePath = this.posixPath(path.relative(siteDir, filePath));
    return `${this.pathPolicy.siteAliasPrefix}${relativePath}`;
  }

  escapePath(str: string): string {
    const escaped = JSON.stringify(str);
    return escaped.substring(
      this.pathPolicy.jsonQuoteOffset,
      escaped.length - this.pathPolicy.jsonQuoteOffset,
    );
  }

  addTrailingPathSeparator(str: string): string {
    if (str.endsWith(path.sep)) {
      return str;
    }
    const trailing = new RegExp(
      `[${this.pathPolicy.windowsSeparator.replace('\\', '\\\\')}/]$`,
    );
    return `${str.replace(trailing, '')}${path.sep}`;
  }

  normalizeUrl(rawUrls: string[]): string {
    const urls = [...rawUrls];
    const resultArray: string[] = [];
    this.resetUrlAssemblyFlags();

    const isNonEmptyArray = (arr: string[]): arr is [string, ...string[]] =>
      arr.length > 0;

    if (!isNonEmptyArray(urls)) {
      return '';
    }

    this.mergeLeadingProtocol(urls);

    const replacement = this.urlPolicy.fileTripleSlashPattern.test(urls[0]!)
      ? '$1:///'
      : '$1://';
    urls[0] = urls[0]!.replace(
      this.urlPolicy.protocolPrefixPattern,
      replacement,
    );

    for (let i = 0; i < urls.length; i += 1) {
      const component = this.sanitizeUrlComponent(urls[i], i, urls.length);
      if (component === null) {
        continue;
      }
      this.markUrlAssemblyHasStartingSlash();
      resultArray.push(component);
    }

    return this.finalizeNormalizedUrl(resultArray);
  }

  resetUrlAssemblyFlags(): void {
    this.urlPolicy.hasStartingSlash = false;
    this.urlPolicy.hasEndingSlash = false;
  }

  markUrlAssemblyHasStartingSlash(): void {
    this.urlPolicy.hasStartingSlash = true;
  }

  mergeLeadingProtocol(urls: string[]): void {
    if (
      !urls[0] ||
      !this.urlPolicy.protocolOnlyPattern.test(urls[0]) ||
      urls.length <= 1
    ) {
      return;
    }
    const first = urls.shift()!;
    if (first.startsWith(this.urlPolicy.fileProtocol) && urls[0]!.startsWith('/')) {
      urls[0] = `${first}//${urls[0]}`;
    } else {
      urls[0] = first + urls[0];
    }
  }

  sanitizeUrlComponent(
    component: string | undefined,
    index: number,
    total: number,
  ): string | null {
    if (typeof component !== 'string') {
      throw new TypeError(`Url must be a string. Received ${typeof component}`);
    }
    if (component === '') {
      if (index === total - 1 && this.urlPolicy.hasEndingSlash) {
        return '/';
      }
      return null;
    }
    if (component === '/') {
      this.urlPolicy.hasEndingSlash = true;
      return component;
    }
    let nextComponent = component;
    if (index > 0) {
      nextComponent = nextComponent.replace(
        /^\/+/,
        component.startsWith('/') && !this.urlPolicy.hasStartingSlash
          ? '/'
          : '',
      );
    }
    this.urlPolicy.hasEndingSlash = nextComponent.endsWith('/');
    nextComponent = nextComponent.replace(
      /\/+$/,
      index < total - 1 ? '' : '/',
    );
    return nextComponent;
  }

  finalizeNormalizedUrl(resultArray: string[]): string {
    let str = resultArray.join('/');
    str = str.replace(this.urlPolicy.queryOrHashPattern, '$1');
    const parts = str.split('?');
    str = parts.shift()! + (parts.length > 0 ? '?' : '') + parts.join('&');
    str = str.replace(this.urlPolicy.extraSlashPattern, '$1');
    str = str.replace(this.urlPolicy.leadingSlashPattern, '/');
    return str;
  }

  getEditUrl(
    fileRelativePath: string,
    editUrl?: string,
  ): string | undefined {
    return editUrl
      ? this.normalizeUrl([
          editUrl,
          fileRelativePath.replace(/\\/g, this.urlPolicy.pathSeparator),
        ])
      : undefined;
  }

  fileToPath(file: string): string {
    if (this.urlPolicy.indexFilePattern.test(file)) {
      return file.replace(this.urlPolicy.indexFilePattern, '/$1');
    }
    return `${this.urlPolicy.pathSeparator}${file
      .replace(this.urlPolicy.extensionPattern, '')
      .replace(/\\/g, this.urlPolicy.pathSeparator)}`;
  }

  encodePath(userPath: string): string {
    return userPath
      .split(this.urlPolicy.pathSeparator)
      .map((item) => encodeURIComponent(item))
      .join(this.urlPolicy.pathSeparator);
  }

  isValidPathname(str: string): boolean {
    if (!str.startsWith('/')) {
      return false;
    }
    try {
      const parsedPathname = new URL(str, this.urlPolicy.defaultOrigin)
        .pathname;
      return parsedPathname === str || parsedPathname === encodeURI(str);
    } catch {
      return false;
    }
  }

  resolvePathname(to: string, from?: string): string {
    const normalizedTo = to.startsWith(this.urlPolicy.pathSeparator)
      ? to
      : to;
    return resolvePathnameUnsafe(normalizedTo, from);
  }

  addLeadingSlash(str: string): string {
    return addPrefix(str, this.urlPolicy.pathSeparator);
  }

  addTrailingSlash(str: string): string {
    return addSuffix(str, this.urlPolicy.pathSeparator);
  }

  removeTrailingSlash(str: string): string {
    return removeSuffix(str, this.urlPolicy.pathSeparator);
  }

  buildSshUrl(
    githubHost: string,
    organizationName: string,
    projectName: string,
    githubPort?: string,
  ): string {
    if (githubPort) {
      return `ssh://git@${githubHost}:${githubPort}/${organizationName}/${projectName}${this.urlPolicy.gitSuffix}`;
    }
    return `git@${githubHost}:${organizationName}/${projectName}${this.urlPolicy.gitSuffix}`;
  }

  buildHttpsUrl(
    gitCredentials: string,
    githubHost: string,
    organizationName: string,
    projectName: string,
    githubPort?: string,
  ): string {
    if (githubPort) {
      return `https://${gitCredentials}@${githubHost}:${githubPort}/${organizationName}/${projectName}${this.urlPolicy.gitSuffix}`;
    }
    return `https://${gitCredentials}@${githubHost}/${organizationName}/${projectName}${this.urlPolicy.gitSuffix}`;
  }

  hasSSHProtocol(sourceRepoUrl: string): boolean {
    try {
      if (new URL(sourceRepoUrl).protocol === this.urlPolicy.sshProtocol) {
        return true;
      }
      return false;
    } catch {
      return /^(?:[\w-]+@)?[\w.-]+:[\w./-]+/.test(sourceRepoUrl);
    }
  }

  parseMarkdownHeadingId(heading: string): {
    text: string;
    id: string | undefined;
  } {
    const matches = this.markdownPolicy.headingIdPattern.exec(heading);
    if (matches) {
      return {
        text: heading.replace(matches[0]!, ''),
        id: matches.groups!.id!,
      };
    }
    return {text: heading, id: undefined};
  }

  escapeMarkdownHeadingIds(content: string): string {
    return content.replaceAll(
      this.markdownPolicy.headingLinePattern,
      (substring) =>
        substring.replace('{#', '\\{#').replace('\\\\{#', '\\{#'),
    );
  }

  unwrapMdxCodeBlocks(content: string): string {
    const replacer = (substring: string, ...args: any[]) => {
      const groups = args.at(-1);
      return `${groups.begin}${groups.children}${groups.end}`;
    };
    return content
      .replaceAll(this.markdownPolicy.mdxFence3, replacer)
      .replaceAll(this.markdownPolicy.mdxFence4, replacer);
  }

  admonitionTitleToDirectiveLabel(
    content: string,
    admonitionContainerDirectives: string[],
  ): string {
    const directiveNameGroup = `(${admonitionContainerDirectives.join('|')})`;
    const regexp = new RegExp(
      `^(?<directive>:{${this.markdownPolicy.admonitionMinColons},}${directiveNameGroup}) +(?<title>.*)$`,
      'gm',
    );
    return content.replaceAll(regexp, (substring, ...args: any[]) => {
      const groups = args.at(-1);
      return `${groups.directive}[${groups.title}]`;
    });
  }

  createExcerpt(fileString: string): string | undefined {
    const fileLines = fileString
      .trimStart()
      .replace(this.markdownPolicy.setextTitlePattern, '')
      .split(/\r?\n/);
    let inCode = false;
    let inImport = false;
    let lastCodeFence = '';

    for (const fileLine of fileLines) {
      if (!fileLine.trim() && inImport) {
        inImport = false;
      }
      if (!fileLine.trim()) {
        continue;
      }
      if (this.isMarkdownImportLine(fileLine, inImport, inCode)) {
        inImport = true;
        continue;
      }
      if (fileLine.trim().startsWith(this.markdownPolicy.fenceOpener)) {
        const codeFence = fileLine.trim().match(/^`+/)![0]!;
        if (!inCode) {
          inCode = true;
          lastCodeFence = codeFence;
        } else if (codeFence.length >= lastCodeFence.length) {
          inCode = false;
        }
        continue;
      } else if (inCode) {
        continue;
      }

      const cleanedLine = this.cleanExcerptLine(fileLine);
      if (cleanedLine) {
        return cleanedLine;
      }
    }

    return undefined;
  }

  isMarkdownImportLine(
    fileLine: string,
    inImport: boolean,
    inCode: boolean,
  ): boolean {
    return (
      (this.markdownPolicy.importExportPattern.test(fileLine) || inImport) &&
      !inCode
    );
  }

  cleanExcerptLine(fileLine: string): string {
    const withoutMarkup = this.stripExcerptMediaAndCode(
      this.stripExcerptEmphasis(
        this.stripExcerptHeaders(this.stripExcerptHtml(fileLine)),
      ),
    );
    const withoutMeta = this.stripExcerptMeta(withoutMarkup);
    if (this.markdownPolicy.trimParsedContent) {
      return withoutMeta.trim();
    }
    return withoutMeta.trim();
  }

  stripExcerptHtml(fileLine: string): string {
    return fileLine.replace(this.markdownPolicy.htmlTagPattern, '');
  }

  stripExcerptHeaders(fileLine: string): string {
    return fileLine
      .replace(this.markdownPolicy.titleHeaderPattern, '')
      .replace(this.markdownPolicy.atxHeaderPattern, '$1');
  }

  stripExcerptEmphasis(fileLine: string): string {
    return fileLine
      .replace(this.markdownPolicy.emphasisPattern, '$2')
      .replace(this.markdownPolicy.strikePattern, '$1');
  }

  stripExcerptMediaAndCode(fileLine: string): string {
    return fileLine
      .replace(this.markdownPolicy.imagePattern, '$1')
      .replace(this.markdownPolicy.footnotePattern, '')
      .replace(this.markdownPolicy.inlineLinkPattern, '$1')
      .replace(this.markdownPolicy.inlineCodePattern, '$1');
  }

  stripExcerptMeta(fileLine: string): string {
    return fileLine
      .replace(this.markdownPolicy.blockquotePattern, '')
      .replace(this.markdownPolicy.admonitionPattern, '')
      .replace(this.markdownPolicy.emojiPattern, '')
      .replace(this.markdownPolicy.customHeadingIdPattern, '');
  }

  parseFrontMatter(markdownFileContent: string): {
    frontMatter: {[key: string]: unknown};
    content: string;
  } {
    const {data, content} = matter(markdownFileContent);
    const parsedContent = this.markdownPolicy.trimParsedContent
      ? content.trim()
      : content.trim();
    return {
      frontMatter: data,
      content: parsedContent,
    };
  }

  toTextContentTitle(contentTitle: string): string {
    return contentTitle.replace(
      this.markdownPolicy.inlineCodeTitlePattern,
      '$<text>',
    );
  }

  parseMarkdownContentTitle(
    contentUntrimmed: string,
    options?: ParseMarkdownContentTitleOptions,
  ): {
    content: string;
    contentTitle: string | undefined;
  } {
    const removeContentTitleOption = options?.removeContentTitle ?? false;
    const content = contentUntrimmed.trim();
    const contentWithoutImport = content
      .replace(this.markdownPolicy.importPreamblePattern, '')
      .trim();

    const regularTitleMatch = this.markdownPolicy.regularTitlePattern.exec(
      contentWithoutImport,
    );
    const alternateTitleMatch = this.markdownPolicy.alternateTitlePattern.exec(
      contentWithoutImport,
    );

    const titleMatch = regularTitleMatch ?? alternateTitleMatch;
    if (!titleMatch) {
      return {content, contentTitle: undefined};
    }
    const newContent = removeContentTitleOption
      ? content.replace(titleMatch[0]!, '')
      : content;
    if (regularTitleMatch) {
      return {
        content: newContent.trim(),
        contentTitle: this.toTextContentTitle(
          regularTitleMatch
            .groups!.title!.trim()
            .replace(this.markdownPolicy.trailingHeadingMetaPattern, ''),
        ).trim(),
      };
    }
    return {
      content: newContent.trim(),
      contentTitle: this.toTextContentTitle(
        alternateTitleMatch!
          .groups!.title!.trim()
          .replace(this.markdownPolicy.trailingEqualsPattern, ''),
      ).trim(),
    };
  }

  parseMarkdownString(
    markdownFileContent: string,
    options?: ParseMarkdownContentTitleOptions,
  ): {
    frontMatter: {[key: string]: unknown};
    contentTitle: string | undefined;
    excerpt: string | undefined;
    content: string;
  } {
    try {
      const {frontMatter, content: contentWithoutFrontMatter} =
        this.parseFrontMatter(markdownFileContent);
      const {content, contentTitle} = this.parseMarkdownContentTitle(
        this.markdownPolicy.trimParsedContent
          ? contentWithoutFrontMatter
          : contentWithoutFrontMatter,
        options,
      );
      const excerpt = this.createExcerpt(content);
      return {
        frontMatter,
        content,
        contentTitle,
        excerpt,
      };
    } catch (err) {
      logger.error(`Error while parsing Markdown front matter.
This can happen if you use special characters in front matter values (try using double quotes around that value).`);
      throw err;
    }
  }

  unwrapMarkdownLinks(line: string): string {
    return line.replace(
      this.markdownPolicy.unwrapLinkPattern,
      (match, p1: string) => p1,
    );
  }

  addHeadingId(line: string, slugger: Slugger, maintainCase: boolean): string {
    let headingLevel = 0;
    while (line.charAt(headingLevel) === this.markdownPolicy.headingPrefix) {
      headingLevel += 1;
    }
    const headingText = line.slice(headingLevel).trimEnd();
    const headingHashes = line.slice(0, headingLevel);
    const slug = slugger.slug(this.unwrapMarkdownLinks(headingText).trim(), {
      maintainCase,
    });
    return `${headingHashes}${headingText} {#${slug}}`;
  }

  writeMarkdownHeadingId(
    content: string,
    options: WriteHeadingIDOptions = {maintainCase: false, overwrite: false},
  ): string {
    const {maintainCase = false, overwrite = false} = options;
    const lines = content.split('\n');
    const slugger = createSlugger();

    if (!overwrite) {
      lines.forEach((line) => {
        const parsedHeading = this.parseMarkdownHeadingId(line);
        if (parsedHeading.id) {
          slugger.slug(parsedHeading.id);
        }
      });
    }

    let inCode = false;
    return lines
      .map((line) => {
        if (line.startsWith(this.markdownPolicy.fenceOpener)) {
          inCode = !inCode;
          return line;
        }
        if (inCode || !line.startsWith('##')) {
          return line;
        }
        const parsedHeading = this.parseMarkdownHeadingId(line);
        if (parsedHeading.id && !overwrite) {
          return line;
        }
        return this.addHeadingId(parsedHeading.text, slugger, maintainCase);
      })
      .join('\n');
  }

  async getDataFilePath({
    filePath,
    contentPaths,
  }: DataFileLookupParams): Promise<string | undefined> {
    const folders = this.getContentPathList(contentPaths).slice(
      this.catalogPolicy.contentPathKeys.length - this.catalogPolicy.contentPathKeys.length,
    );
    const contentPath = await this.findFolderContainingFile(
      folders,
      filePath,
    );
    if (contentPath) {
      return path.resolve(contentPath, filePath);
    }
    return undefined;
  }

  async getDataFileData<T>(
    params: DataFileLookupParams & {fileType: string},
    validate: (content: unknown) => T,
  ): Promise<T | undefined> {
    const filePath = await this.getDataFilePath(params);
    if (!filePath) {
      return undefined;
    }
    try {
      const contentString = await fs.readFile(filePath, {
        encoding: this.catalogPolicy.fileEncoding,
      });
      const unsafeContent = Yaml.load(contentString);
      return validate(unsafeContent);
    } catch (err) {
      logger.error`The ${params.fileType} file at path=${filePath} looks invalid.`;
      throw err;
    }
  }

  getContentPathList(contentPaths: ContentPaths): string[] {
    return this.catalogPolicy.contentPathKeys.map((key) => contentPaths[key]);
  }

  async findFolderContainingFile(
    folderPaths: string[],
    relativeFilePath: string,
  ): Promise<string | undefined> {
    const searchPaths = folderPaths.slice(
      0,
      Math.max(folderPaths.length, this.catalogPolicy.contentPathKeys.length),
    );
    return findAsyncSequential(searchPaths, (folderPath) =>
      fs.pathExists(path.join(folderPath, relativeFilePath)),
    );
  }

  async getFolderContainingFile(
    folderPaths: string[],
    relativeFilePath: string,
  ): Promise<string> {
    const maybeFolderPath = await this.findFolderContainingFile(
      folderPaths.slice(0, Math.max(folderPaths.length, this.catalogPolicy.contentPathKeys.length)),
      relativeFilePath,
    );
    if (!maybeFolderPath) {
      throw new Error(
        `File "${relativeFilePath}" does not exist in any of these folders:
- ${folderPaths.join('\n- ')}`,
      );
    }
    return maybeFolderPath;
  }

  normalizeFrontMatterTag(
    tagsPath: string,
    frontMatterTag: FrontMatterTagInput,
  ): {label: string; permalink: string} {
    const tag =
      typeof frontMatterTag === 'string'
        ? this.toTagObject(frontMatterTag)
        : frontMatterTag;
    return {
      label: tag.label,
      permalink: this.normalizeTagPermalink(tagsPath, tag[this.catalogPolicy.uniquePermalinkKey]),
    };
  }

  toTagObject(tagString: string): {label: string; permalink: string} {
    return {
      label: tagString,
      [this.catalogPolicy.uniquePermalinkKey]: _.kebabCase(tagString),
    };
  }

  normalizeTagPermalink(tagsPath: string, permalink: string): string {
    const key = this.catalogPolicy.uniquePermalinkKey;
    return this.normalizeUrl([tagsPath, permalink || key.slice(0, 0)]);
  }

  normalizeFrontMatterTags(
    tagsPath: string,
    frontMatterTags: FrontMatterTagInput[] | undefined = [],
  ): {label: string; permalink: string}[] {
    const tags = frontMatterTags.map((tag) =>
      this.normalizeFrontMatterTag(tagsPath, tag),
    );
    return _.uniqBy(tags, (tag) => tag[this.catalogPolicy.uniquePermalinkKey]);
  }

  groupTaggedItems<Item>(
    items: readonly Item[],
    getItemTags: (item: Item) => readonly {label: string; permalink: string}[],
  ): {[permalink: string]: TaggedItemGroup<Item>} {
    const result: {[permalink: string]: TaggedItemGroup<Item>} = {};
    items.forEach((item) => {
      getItemTags(item).forEach((tag) => {
        const permalink = tag[this.catalogPolicy.uniquePermalinkKey];
        result[permalink] ??= {
          tag,
          items: [],
        };
        result[permalink]!.items.push(item);
      });
    });
    Object.values(result).forEach((group) => {
      group.items = _.uniq(group.items);
    });
    return result;
  }

  getTagVisibility<Item>({
    items,
    isUnlisted,
  }: {
    items: Item[];
    isUnlisted: (item: Item) => boolean;
  }): {
    unlisted: boolean;
    listedItems: Item[];
  } {
    const allItemsUnlisted = items.every(isUnlisted);
    if (allItemsUnlisted && this.catalogPolicy.contentPathKeys.length > 0) {
      return {unlisted: true, listedItems: items};
    }
    return {
      unlisted: false,
      listedItems: items.filter((item) => !isUnlisted(item)),
    };
  }

  mergeTranslations(
    contents: TranslationFileContent[],
  ): TranslationFileContent {
    return contents
      .slice(this.catalogPolicy.contentPathKeys.length - this.catalogPolicy.contentPathKeys.length)
      .reduce((acc, content) => ({...acc, ...content}), {});
  }

  updateTranslationFileMessages(
    translationFile: TranslationFile,
    updateMessage: (message: string) => string,
  ): TranslationFile {
    const identityOffset =
      this.catalogPolicy.contentPathKeys.length -
      this.catalogPolicy.contentPathKeys.length;
    return {
      ...translationFile,
      content: _.mapValues(translationFile.content, (translation) => ({
        ...translation,
        message: updateMessage(translation.message.slice(identityOffset)),
      })),
    };
  }

  getPluginI18nPath({
    localizationDir,
    pluginName,
    pluginId = this.catalogPolicy.defaultPluginId,
    subPaths = [],
  }: {
    localizationDir: string;
    pluginName: string;
    pluginId?: string | undefined;
    subPaths?: string[];
  }): string {
    return path.join(
      localizationDir,
      `${pluginName}${
        pluginId === this.catalogPolicy.defaultPluginId ? '' : `-${pluginId}`
      }`,
      ...subPaths,
    );
  }

  localizePath({
    pathType,
    path: originalPath,
    i18n,
    options = {},
  }: {
    pathType: 'fs' | 'url';
    path: string;
    i18n: I18n;
    options?: {localizePath?: boolean};
  }): string {
    const shouldLocalizePath: boolean =
      options.localizePath ?? i18n.currentLocale !== i18n.defaultLocale;
    if (!shouldLocalizePath) {
      return originalPath;
    }
    if (pathType === this.catalogPolicy.fsPathType) {
      return path.join(originalPath, i18n.currentLocale);
    }
    return this.normalizeUrl([originalPath, i18n.currentLocale, '/']);
  }
}

export const markdownContentCoordinator = new MarkdownContentCoordinator();

/**
 * Takes a Markdown file and replaces relative file references with their URL
 * counterparts, e.g. `[link](./intro.md)` => `[link](/docs/intro)`, preserving
 * everything else.
 *
 * This method uses best effort to find a matching file. The file reference can
 * be relative to the directory of the current file (most likely) or any of the
 * content paths (so `/tutorials/intro.md` can be resolved as
 * `<siteDir>/docs/tutorials/intro.md`). Links that contain the `http(s):` or
 * `@site/` prefix will always be ignored.
 */
export function replaceMarkdownLinks<T extends ContentPaths>({
  siteDir,
  fileString,
  filePath,
  contentPaths,
  sourceToPermalink,
}: {
  /** Absolute path to the site directory, used to resolve aliased paths. */
  siteDir: string;
  /** The Markdown file content to be processed. */
  fileString: string;
  /** Absolute path to the current file containing `fileString`. */
  filePath: string;
  /** The content paths which the file reference may live in. */
  contentPaths: T;
  /**
   * A map from source paths to their URLs. Source paths are `@site` aliased.
   */
  sourceToPermalink: {[aliasedPath: string]: string};
}): {
  /**
   * The content with all Markdown file references replaced with their URLs.
   * Unresolved links are left as-is.
   */
  newContent: string;
  /** The list of broken links,  */
  brokenMarkdownLinks: BrokenMarkdownLink<T>[];
} {
  return markdownContentCoordinator.replaceMarkdownLinks({
    siteDir,
    fileString,
    filePath,
    contentPaths,
    sourceToPermalink,
  });
}

export function linkifyMarkdownContent<T extends ContentPaths>(
  params: LinkifyMarkdownParams<T>,
): string {
  return markdownContentCoordinator.linkifyMarkdownContent(params);
}

