    lastCodeFence = this.updateFenceContext(line, lastCodeFence);
    if (this.isInsideFencedBlock(lastCodeFence)) {
      return line;
    }

    let modifiedLine = line;
    // Replace inline-style links or reference-style links e.g:
    // This is [Document 1](doc1.md)
    // [doc1]: doc1.md
    const mdRegex =
      /(?:\]\(|\]:\s*)(?!https?:\/\/|@site\/)<?(?<filename>[^'"\]\s>]+(?:\s[^'"\]\s>]+)*\.mdx?)>?/g;
    let mdMatch = mdRegex.exec(modifiedLine);
    while (mdMatch !== null) {
      // Replace it to correct html link.
      const mdLink = mdMatch.groups!.filename!;

      const sourcesToTry = this.collectMarkdownLinkSources(
        mdLink,
        filePath,
        siteDir,
        contentPaths,
      );

      const aliasedSourceMatch = this.resolveAliasedPermalink(
        sourcesToTry,
        mdLink,
        siteDir,
        sourceToPermalink,
      );

      const permalink: string | undefined = aliasedSourceMatch
        ? sourceToPermalink[aliasedSourceMatch]
        : undefined;

      if (permalink) {
        // MDX won't be happy if the permalink contains a space, we need to
        // convert it to %20
        const encodedPermalink = this.encodePermalinkSpaces(permalink).replace(
          /%20/g,
          spaceEncoding,
        );
        modifiedLine = modifiedLine.replace(
          mdMatch[0]!,
          mdMatch[0]!.replace(mdLink, encodedPermalink),
        );
        // Adjust the lastIndex to avoid passing over the next link if the
        // newly replaced URL is shorter.
        mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
      } else {
        this.recordBrokenMarkdownLink(
          brokenMarkdownLinks,
          contentPaths,
          filePath,
          mdLink,
        );
      }
      mdMatch = mdRegex.exec(modifiedLine);
    }
    return modifiedLine;
  });

  const newContent = lines.join('\n');

  return {newContent, brokenMarkdownLinks};
}

