import {replaceMarkdownLinks} from '../markdownLinks';

describe('issue #8927 repro', () => {
  it('does not rewrite paths whose directory name contains the doc filename', () => {
    const input = `
![my image](./file.md__static_image_assets__/image.png)
[some image](./file.md__static_image_assets/image.png)
`;
    expect(
      replaceMarkdownLinks({
        siteDir: '.',
        filePath: 'docs/file.md',
        contentPaths: {
          contentPath: 'docs',
          contentPathLocalized: 'i18n/docs-localized',
        },
        sourceToPermalink: {
          '@site/docs/file.md': '/docs/file',
        },
        fileString: input,
      }),
    ).toEqual({
      newContent: input,
      brokenMarkdownLinks: [],
    });
  });
});

